import 'package:flutter_storage_info/flutter_storage_info.dart';

void main() async {
  int total = await FlutterStorageInfo.storageTotalSpace;
  int free = await FlutterStorageInfo.storageFreeSpace;
  int used = await FlutterStorageInfo.storageUsedSpace;
  print('Total: $total, Free: $free, Used: $used');
}
